class NotIntError(Exception):
    def __init__(self, message):        
        self.message = message
    def __str__(self):
        return self.message
def dich(num,typ="len",maximum=100):
    if typ=="len" or typ=="lenp":
        low=0
        hi=100
        guess=50
        leng=0
        lenp=[]
        while guess!=num:
            if guess<num:
                low=guess
                guess=round((low+hi)/2)
            elif guess>num:
                hi=guess
                guess=round((low+hi)/2)
            leng+=1
            lenp.append(guess)
        if typ=="lenp":
            return lenp
        return leng
def tnpo(x,y="next"):
    if y=="next":
        try:
            tmp=int(str(x))
        except:
            raise NotIntError("2n+1 requires an 'int' input number.")
        if x%2==1:
            return 2*(x+1)
        else:
            return x/2
    if y=="len" or y=="lenp":
        try:        
            tmp=int(x)
        except:
            raise NotIntError("2n+1 requires an 'int' input number.")
        z=0
        w=x
        n=[w]
        while w!=4 and w!=2 and w!=1:
            if w%2==1:
                w=2*(w+1)
            else:
                w=int(w/2)
            if y=="lenp":
                n.append(w)
            z+=1
        n[0]=z
        if y=="lenp":
            return n
        return z
    if y=="best":
        try:        
            tmp=int(x)
        except:
            raise NotIntError("2n+1 requires an 'int' input number.")
        return (2**x)+2
    else:
        return Exception("Nothing to do!")
def fact(x):
    tmp=1
    for i in range(1,x+1):
        tmp=tmp*i
    return tmp
def efunc(x):
    z=1
    for i in range(1,x+1):
        z+=(1/fact(i))
    return z
e=efunc(1000)
def roundb(num,inc=1):
    return inc*round(num/inc)
def floor(num,inc=1):
    return num-(num%inc)
def ceil(num,inc=1):
    return (num-(num%inc))+inc
